{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions. In 2020, approximately 3.3 billion USD was invested globally for malaria interventions, falling short of the targeted 6.8 billion USD set by the GTS, increasing the financial gap between desirable and actual investment. Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets.",
      "reason": "The abstract describes the current state of knowledge regarding malaria control, the financing gap, and the role of optimization models in addressing resource constraints."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The abstract explicitly states the aim of the review, which establishes the need to identify, characterize, and assess the strengths and limitations of existing models for malaria control optimization."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that this is an update or replication of a previous systematic review, nor does it mention the existence of similar systematic reviews that would necessitate a justification for this specific review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review focuses on 'models for malaria control optimization' rather than evaluating the effects of a specific intervention itself; therefore, describing a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a systematic review of existing models, not a primary study of a complex intervention or delivery context that would require a logic model."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The review explicitly states both a research question and the main aim/objective of the review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of models for malaria control optimization, not a review of intervention effects (e.g., a clinical trial meta-analysis), therefore PICO is not the required framework for this type of review."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024; (3) Studies were included irrespective of the targeted geographical regions; (4) Studies were included irrespective of the population subgroups; (5) Studies containing an optimization model (mathematical or statistical); (6) All studies with human Plasmodium species; (7) Studies with two or more interventions; (8) Cost data were used in combination with the model outputs; (9) Outcomes/health benefits were clearly stated and/or measured.",
      "reason": "The manuscript explicitly lists the inclusion criteria, covering study design (optimization models), population (human Plasmodium species), and specific requirements for interventions and data (cost data, two or more interventions)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024",
      "reason": "The manuscript specifies report characteristics including language (English) and publication date (before 30th June 2024)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; the exclusion criteria provided in the text (chunk_id: text_9) are based on study type, language, and publication status."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "A narrative synthesis of the study characteristics was performed. All studies investigated WHO-recommended interventions for control or elimination targets (Table 2)... The administrative level of data analysis (Table 4) varied between national/multinational only (40.0%), national/ Table 2 Summary of models for malaria control optimization studies",
      "reason": "The manuscript describes how studies were grouped for synthesis, specifically by intervention type (Table 2) and administrative level of analysis (Table 4), which are linked to the review's objective of characterizing models for malaria control optimization."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not provide specific rationales for notable restrictions on study eligibility (e.g., why only English language or peer-reviewed journals were selected), nor does it appear to have 'notable' restrictions that require specific justification beyond standard systematic review practice."
    }
  ],
  "confidence": 100
}

